// ---------------------------------------------------------------------------
// Real Monad mainnet receipts, fetched from the chain, not written by hand.
//
// Generated rather than composed on purpose. A decoder tested against logs
// its author typed out tests the author's belief about the format; these are
// byte-for-byte what rpc.monad.xyz returned on 2026-10-02, so a wrong belief
// about word order or topic meaning fails here instead of in production.
//
// Every expected MON figure in the suite was cross-checked against a
// callTracer trace of the same transaction before being written down — two
// independent sources, one of them not the thing under test.
//
// Logs are kept COMPLETE, not trimmed to the ones the decoder reads. The
// unrelated ones are the test: a decoder that matches too loosely picks them
// up, and a fixture pruned to the interesting logs would never show it.
// ---------------------------------------------------------------------------

import type { MinimalReceipt } from "./kuru-history";

export interface Fixture {
  hash: string;
  /** The transaction's own `value` — MON sent, non-zero only on a sell. */
  value: bigint;
  receipt: MinimalReceipt;
}

